Here are the MSTest comparison assertions you need for boundary testing your `ScoreCalculator`:

## Comparison Assertions (MSTest 3.x+)

```csharp
Assert.IsGreaterThan(lowerBound, actual);   // actual > lowerBound
Assert.IsLessThan(upperBound, actual);      // actual < upperBound
Assert.IsInRange(actual, low, high);        // low <= actual <= high
```

## Example Tests for Your ScoreCalculator

```csharp
[TestClass]
public sealed class ScoreCalculatorTests
{
    private readonly ScoreCalculator _calculator = new();

    [TestMethod]
    [DataRow(7, 10, 70.0)]
    [DataRow(10, 10, 100.0)]
    [DataRow(0, 5, 0.0)]
    public void CalculatePercentage_ValidInputs_ReturnsExpected(int correct, int total, double expected)
    {
        var result = _calculator.CalculatePercentage(correct, total);
        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    public void CalculatePercentage_Result_IsInValidRange()
    {
        var result = _calculator.CalculatePercentage(3, 7);
        Assert.IsInRange(result, 0.0, 100.0);
    }

    [TestMethod]
    public void NormalizeScore_PartialCredit_IsGreaterThanZero()
    {
        var result = _calculator.NormalizeScore(25.0, 50.0);
        Assert.IsGreaterThan(0.0, result);
    }

    [TestMethod]
    public void NormalizeScore_OverMax_CapsAt100()
    {
        var result = _calculator.NormalizeScore(120.0, 100.0);
        Assert.AreEqual(100.0, result);
    }

    [TestMethod]
    public void NormalizeScore_AnyValidInput_NeverExceeds100()
    {
        var result = _calculator.NormalizeScore(999.0, 50.0);
        Assert.IsLessThan(100.1, result); // actual < upperBound
    }

    [TestMethod]
    [DataRow(90.0, "A")]
    [DataRow(89.9, "B")]
    [DataRow(80.0, "B")]
    [DataRow(70.0, "C")]
    [DataRow(60.0, "D")]
    [DataRow(59.9, "F")]
    public void GetGrade_BoundaryValues_ReturnsCorrectGrade(double pct, string expected)
    {
        Assert.AreEqual(expected, _calculator.GetGrade(pct));
    }

    [TestMethod]
    public void CalculatePercentage_NegativeCorrect_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(-1, 10));
    }

    [TestMethod]
    public void CalculatePercentage_ZeroTotal_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(0, 0));
    }

    [TestMethod]
    public void CalculatePercentage_CorrectExceedsTotal_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(11, 10));
    }
}
```

## Key Takeaways

| Scenario | Assertion |
|----------|-----------|
| Score > 0 | `Assert.IsGreaterThan(0.0, result)` |
| Score < cap | `Assert.IsLessThan(cap, result)` |
| Score within bounds | `Assert.IsInRange(result, low, high)` |
| Exact boundary value | `Assert.AreEqual(expected, result)` |
| Invalid input throws | `Assert.ThrowsExactly<T>(() => ...)` |

These produce clear failure messages like `"Expected value to be greater than 0.0, but was -5.0"` — far better than `Assert.IsTrue(result > 0)`.
